import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;

public class DigitFieldGuardTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static boolean type(javax.swing.JTextField field, char ch) {
        KeyEvent event = new KeyEvent(field, KeyEvent.KEY_TYPED,
                System.currentTimeMillis(), 0, KeyEvent.VK_UNDEFINED, ch);
        for (KeyListener listener : field.getKeyListeners()) {
            listener.keyTyped(event);
        }
        return event.isConsumed();
    }

    public static void main(String[] args) {
        try {
            DigitFieldGuard panel = new DigitFieldGuard();
            javax.swing.JTextField field = (javax.swing.JTextField) find(panel, "amount");

            check("a KeyListener is registered on the field", true,
                    field.getKeyListeners().length >= 1);
            check("nothing rejected yet", 0, panel.rejectedCount());

            check("a digit on an empty field is allowed", false, type(field, '5'));
            check("still nothing rejected", 0, panel.rejectedCount());

            check("a letter is consumed", true, type(field, 'x'));
            check("a dot is consumed", true, type(field, '.'));
            check("two rejections counted", 2, panel.rejectedCount());

            field.setText("12");
            check("a digit with room to spare is allowed", false, type(field, '0'));

            field.setText("1234");
            check("a digit past the limit is consumed", true, type(field, '7'));
            check("three rejections counted", 3, panel.rejectedCount());
            check("backspace works even when full", false, type(field, '\b'));
            check("backspace is never a rejection", 3, panel.rejectedCount());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

